window.docContents[88].resolve({"/Typeclasses/#Logical-Foundations--Typeclasses--Maps":{"contents":"Maps (or \"dictionaries\") are ubiquitous data structures both in ordinary programming and in the theory of programming languages; we're going to need them in many places in later volumes.\n\nWe'll define two flavors of maps: total maps, which include a \"default\" element to be returned when a key being looked up doesn't exist, and partial maps, which instead return an option to indicate success or failure. Partial maps are defined in terms of total maps, using none as the default element.\n\n\n\n\n\n\n\n\n\n","context":"Logical Foundations\u0009Typeclasses","header":"11.5. Maps","id":"/Typeclasses/#Logical-Foundations--Typeclasses--Maps"}});